def solve():
    run_rate = Q("45.5")                      # USD million per year, pre-tax
    realization = {1: Q("0.35"), 2: Q("0.85")}  # full (1.0) from year 3 onward
    integration = {1: Q(52), 2: Q(14)}        # USD million, none later
    tax = Q(19) / 100

    def net_cf(year):
        # After-tax net cash flow; negative pre-tax net gets a tax credit at the same rate
        savings = run_rate * realization.get(year, Q(1))
        cost = integration.get(year, Q(0))
        return (savings - cost) * (1 - tax)

    year1_net = net_cf(1)

    # Walk forward year by year to find when cumulative first reaches >= 0
    cumulative = Q(0)
    cum_end = {}
    breakeven_year = None
    breakeven_time = None
    for k in range(1, 200):
        cf = net_cf(k)
        start = cumulative
        cumulative = cumulative + cf
        cum_end[k] = cumulative
        if breakeven_year is None and cumulative >= 0:
            breakeven_year = k
            if k == 1 and year1_net >= 0:
                breakeven_time = Q(0)
            else:
                shortfall = -start  # positive shortfall at start of year k
                breakeven_time = (k - 1) + shortfall / cf
        if breakeven_year is not None and k >= 2:
            break

    return {
        "final": breakeven_time,
        "year1_net_after_tax": year1_net,       # signed, negative = net cost
        "cumulative_end_year2": cum_end[2],     # signed cumulative balance at end of year 2
        "breakeven_year": breakeven_year,
    }

def solve():
    run_rate = Q("49.5")
    phase = [Q("0.4"), Q("0.7")]
    integ = [Q(52), Q("7.5")]
    t = Q(34) / 100

    def net(year):
        pct = phase[year - 1] if year <= 2 else Q(1)
        cost = integ[year - 1] if year <= 2 else Q(0)
        pre = run_rate * pct - cost
        return pre * (1 - t)

    y1 = net(1)
    cum = Q(0)
    be_year = None
    be_time = None
    cum_end2 = None
    for k in range(1, 20):
        n = net(k)
        start = cum
        cum = cum + n
        if k == 2:
            cum_end2 = cum
        if be_year is None and cum >= 0:
            be_year = k
            if y1 >= 0:
                be_time = Q(0)
            else:
                be_time = (k - 1) + (-start) / n
        if k >= 2 and be_year is not None:
            break
    if cum_end2 is None:
        cum_end2 = net(1) + net(2)
    return {
        "final": be_time,
        "year1_net_after_tax": y1,
        "cumulative_end_year2": cum_end2,
        "breakeven_year": be_year,
    }
